import sys; sys.path.insert(0,"/tmp"); from harness import *
import os, shutil,time
def fresh(files):
    base="/tmp/fxops"; shutil.rmtree(base,ignore_errors=True); os.makedirs(base)
    for name,content in files.items():
        p=os.path.join(base,name)
        if content is None: os.makedirs(p)
        else: open(p,"w").write(content)
    return base
def ls(base="/tmp/fxops"):
    out=[]
    for root,d,f in os.walk(base):
        for x in sorted(d+f): out.append(os.path.relpath(os.path.join(root,x),base))
    return sorted(out)
def trash_ls():
    t=os.path.expanduser("~/.local/share/felix/Trash")
    out=[]
    for root,d,f in os.walk(t):
        for x in d+f: out.append(os.path.relpath(os.path.join(root,x),t))
    return sorted(out)
# clean trash before
shutil.rmtree(os.path.expanduser("~/.local/share/felix/Trash"),ignore_errors=True); os.makedirs(os.path.expanduser("~/.local/share/felix/Trash"),exist_ok=True)

base=fresh({"dirA":None,"dirA/file_in_dir":"inside","file1.txt":"hello\n","file2.txt":"world\n"})
