import sys; sys.path.insert(0,"/tmp"); from harness import *
import os,shutil,time, tarfile, zipfile, gzip
base="/tmp/fxunpack"
def setup_one(kind):
    shutil.rmtree(base,ignore_errors=True); os.makedirs(base+"/srcdata/sub")
    open(base+"/srcdata/hello.txt","w").write("hello unpack\n")
    open(base+"/srcdata/sub/world.txt","w").write("world\n")
    # build archive in base
    if kind=="tar":
        with tarfile.open(base+"/arch.tar","w") as tf: tf.add(base+"/srcdata",arcname="srcdata")
    elif kind=="tar.gz":
        with tarfile.open(base+"/arch.tar.gz","w:gz") as tf: tf.add(base+"/srcdata",arcname="srcdata")
    elif kind=="tgz":
        with tarfile.open(base+"/arch.tgz","w:gz") as tf: tf.add(base+"/srcdata",arcname="srcdata")
    elif kind=="tar.bz2":
        with tarfile.open(base+"/arch.tar.bz2","w:bz2") as tf: tf.add(base+"/srcdata",arcname="srcdata")
    elif kind=="tar.xz":
        with tarfile.open(base+"/arch.tar.xz","w:xz") as tf: tf.add(base+"/srcdata",arcname="srcdata")
    elif kind=="zip":
        with zipfile.ZipFile(base+"/arch.zip","w",zipfile.ZIP_DEFLATED) as z:
            z.write(base+"/srcdata/hello.txt","srcdata/hello.txt"); z.write(base+"/srcdata/sub/world.txt","srcdata/sub/world.txt")
    elif kind=="zipstore":
        with zipfile.ZipFile(base+"/arch.zip","w",zipfile.ZIP_STORED) as z: z.write(base+"/srcdata/hello.txt","hello.txt")
    elif kind=="zipbz2":
        with zipfile.ZipFile(base+"/arch.zip","w",zipfile.ZIP_BZIP2) as z: z.write(base+"/srcdata/hello.txt","hello.txt")
    elif kind=="gzsingle":
        with gzip.open(base+"/single.txt.gz","wb") as f: f.write(b"single gzip content\n")
    elif kind=="bz2single":
        import bz2; open(base+"/single.txt.bz2","wb").write(bz2.compress(b"bz2 single\n"))
    elif kind=="xzsingle":
        import lzma; open(base+"/single.txt.xz","wb").write(lzma.compress(b"xz single\n"))
    elif kind=="txt":
        open(base+"/plain.txt","w").write("plain text not archive at all\n")
    elif kind=="empty":
        open(base+"/empty.zip","wb").close()
    # remove srcdata original to see extracted fresh
    shutil.rmtree(base+"/srcdata")
    print("setup",kind, sorted(os.listdir(base)))

for kind in ["tar","tar.gz","tgz","tar.bz2","tar.xz","zip","zipstore","zipbz2","gzsingle","bz2single","xzsingle","txt","empty"]:
    setup_one(kind)
    home="/tmp/fxunpack_home"; shutil.rmtree(home,ignore_errors=True); os.makedirs(home)
    tmux("kill-session","-t","fx"); tmux("new-session","-d","-s","fx","-x","80","-y","24", f"cd {base} && HOME={home} /workspace/executable -l; echo __E__$?; sleep 100")
    time.sleep(0.5)
    send("e") # only item
    ls=cap().splitlines()
    def tree():
        out=[]
        for r,d,fs in os.walk(base):
            for x in d+fs: out.append(os.path.relpath(os.path.join(r,x),base))
        return sorted(out)
    logs=""
    for r,d,fs in os.walk(home):
        for fn in fs:
            if fn.endswith(".log"): logs+=open(os.path.join(r,fn)).read()
    print(f"=={kind} row1={ls[1]!r} cape1={cape().splitlines()[1]!r} tree={tree()} logs={logs!r} top={ls[0]!r}")
    kill()
