#!/usr/bin/env python3
import os, sys, re, time, stat, shutil, subprocess, signal
import unicodedata, functools, traceback

# ---- embedded texts are inserted below ----
HELP_TEXT = ""
INIT_TEXT = ""

def eprint(s=""):
    sys.stderr.write(str(s) + "\n")

def rust_io_error(e):
    if isinstance(e, OSError):
        msg = e.strerror or str(e)
        # Python strerror matches libc/Rust wording for common errnos, but
        # capitalisation of a few differs in Rust messages.
        # Rust io::Error display is e.g. "No such file or directory (os error 2)".
        return f"{msg} (os error {e.errno})"
    return str(e)

def os_error_from_errno(errno_value):
    return f"{os.strerror(errno_value)} (os error {errno_value})"

# -- unicode width handling --
def char_width(ch):
    if ch == "\n" or ch == "\r":
        return 0
    if unicodedata.combining(ch):
        return 0
    cat = unicodedata.category(ch)
    if cat.startswith("C") and ch not in ("\ufe0f",):
        # control / format (including BOM/ZWJ) are zero-width for our layout
        return 0
    if unicodedata.east_asian_width(ch) in ("W", "F"):
        return 2
    # A number of emoji/symbol ranges are double width in unicode-width.
    o = ord(ch)
    if o >= 0x1F300 or (0x2600 <= o <= 0x27BF):
        return 2
    return 1

def str_width(s):
    return sum(char_width(ch) for ch in s)

def truncate_to_width(s, max_width, ellipsis=".."):
    """Truncate s to max_width display cells, using .. suffix like felix for names.
       ellipsis='' gives hard truncation (used for general clipping)."""
    if max_width <= 0:
        return ""
    if str_width(s) <= max_width:
        return s
    if ellipsis:
        if max_width <= len(ellipsis):
            # At very small widths felix still shows prefix + .. filling width.
            limit = max(0, max_width - len(ellipsis))
            out = []
            w = 0
            for ch in s:
                cw = char_width(ch)
                if w + cw > limit:
                    break
                out.append(ch); w += cw
            return "".join(out) + ellipsis[:max_width]
        limit = max_width - len(ellipsis)
    else:
        limit = max_width
    out = []
    w = 0
    for ch in s:
        cw = char_width(ch)
        if w + cw > limit:
            break
        out.append(ch); w += cw
    return "".join(out) + ellipsis

def clip_to_width(s, max_width):
    return truncate_to_width(s, max_width, ellipsis="")

def pad_to_width(s, width):
    w = str_width(s)
    if w >= width:
        return clip_to_width(s, width)
    return s + " " * (width - w)

def wrap_hard_line(line, width):
    """Wrap one logical line into chunks of at most width display cells.
       Tabs were expanded before calling. Empty line -> one empty chunk."""
    if width <= 0:
        return [""]
    if line == "":
        return [""]
    chunks = []
    cur = []
    curw = 0
    for ch in line:
        cw = char_width(ch)
        if cw == 0:
            cur.append(ch)
            continue
        if curw + cw > width and cur:
            chunks.append("".join(cur))
            cur = [ch]; curw = cw
        else:
            cur.append(ch); curw += cw
    if cur or not chunks:
        chunks.append("".join(cur))
    return chunks

def wrap_text_lines(lines, width):
    out = []
    for line in lines:
        out.extend(wrap_hard_line(line, width))
    return out

# -- natural (version-like) comparison --
def _is_ascii_digit(ch):
    return "0" <= ch <= "9"

def _cmp_digit_runs(a, b):
    if a == b:
        return 0
    a0 = a.startswith("0")
    b0 = b.startswith("0")
    if a0 and b0:
        # Treat as decimal fractions: pad on the right, shorter first on tie.
        L = max(len(a), len(b))
        af = a.ljust(L, "0"); bf = b.ljust(L, "0")
