    try:
        n = int(n)
    except Exception:
        n = 0
    if n < 1000:
        return f"{n}B"
    if n < 1000_000:
        return f"{n // 1000}KB"
    if n < 1000_000_000:
        return f"{n // 1000_000}MB"
    return f"{n // 1000_000_000}GB"

def format_date(mtime):
    try:
        t = time.localtime(mtime)
    except Exception:
        t = time.localtime(0)
    return time.strftime("%Y-%m-%d %H:%M", t)

