    except Exception:
        return "Invalid unicode name"

def rust_path_debug(p):
    # Debug formatting of a Rust PathBuf: quoted, escaped.
    s = path_display(p)
    out = s.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n").replace("\r", "\\r").replace("\t", "\\t")
    return '"' + out + '"'

def rust_debug_list(paths):
    return "[" + ", ".join(rust_path_debug(p) for p in paths) + "]"

