# ---------------- YAML (small subset sufficient for felix config) ----------------
class YNode:
    __slots__=("kind","value","line","col","tag")
    def __init__(self,kind,value,line=1,col=1,tag=None):
        self.kind=kind; self.value=value; self.line=line; self.col=col; self.tag=tag

class YamlParseError(Exception):
    pass

def _yaml_strip_comment(s):
    in_s=in_d=False; esc=False
    for i,ch in enumerate(s):
        if in_d:
            if esc: esc=False
            elif ch=='\\': esc=True
            elif ch=='"': in_d=False
        elif in_s:
            if ch=="'":
                if i+1<len(s) and s[i+1]=="'": pass
                else: in_s=False
        else:
            if ch=='"': in_d=True
            elif ch=="'": in_s=True
            elif ch=='#' and (i==0 or s[i-1].isspace()):
                return s[:i].rstrip()
    return s.rstrip()

def _yaml_unquote(token):
    token=token.strip()
    if len(token)>=2 and token[0]=='"' and token[-1]=='"':
        try:
            return bytes(token[1:-1],"utf-8").decode("unicode_escape")
        except Exception:
            return token[1:-1]
    if len(token)>=2 and token[0]=="'" and token[-1]=="'":
        return token[1:-1].replace("''","'")
    return token

def _yaml_split_flow(s):
    parts=[]; cur=[]; depth=0; in_s=in_d=False; esc=False
    for ch in s:
        if in_d:
            cur.append(ch)
            if esc: esc=False
            elif ch=='\\': esc=True
            elif ch=='"': in_d=False
            continue
        if in_s:
            cur.append(ch)
            if ch=="'": in_s=False
            continue
        if ch=='"': in_d=True; cur.append(ch)
        elif ch=="'": in_s=True; cur.append(ch)
        elif ch in '[{': depth+=1; cur.append(ch)
        elif ch in ']}': depth-=1; cur.append(ch)
        elif ch==',' and depth==0:
            parts.append("".join(cur).strip()); cur=[]
        else: cur.append(ch)
    if cur or s.strip()=="": parts.append("".join(cur).strip())
    return parts

def _yaml_parse_flow_or_scalar(text,line,col):
    text=text.strip(); col=col+(len(text)-len(text.lstrip())) if False else col
    if text.startswith("!"):
        # tagged node: !Tag rest
        m=re.match(r'!([A-Za-z0-9_\-]+)\s*(.*)$',text,re.S)
        if m:
            rest=m.group(2).strip()
            inner=_yaml_parse_flow_or_scalar(rest,line,col) if rest else YNode("scalar","",line,col)
            inner.tag=m.group(1)
