# ---------------- YAML (small subset sufficient for felix config) ----------------
class YNode:
    __slots__=("kind","value","line","col","tag")
    def __init__(self,kind,value,line=1,col=1,tag=None):
        self.kind=kind; self.value=value; self.line=line; self.col=col; self.tag=tag

class YamlParseError(Exception):
    pass

def _yaml_strip_comment(s):
    in_s=in_d=False; esc=False
    for i,ch in enumerate(s):
        if in_d:
            if esc: esc=False
            elif ch=='\\': esc=True
            elif ch=='"': in_d=False
        elif in_s:
            if ch=="'":
                if i+1<len(s) and s[i+1]=="'": pass
                else: in_s=False
        else:
            if ch=='"': in_d=True
            elif ch=="'": in_s=True
            elif ch=='#' and (i==0 or s[i-1].isspace()):
                return s[:i].rstrip()
    return s.rstrip()

def _yaml_unquote(token):
    token=token.strip()
    if len(token)>=2 and token[0]=='"' and token[-1]=='"':
        try:
            return bytes(token[1:-1],"utf-8").decode("unicode_escape")
        except Exception:
            return token[1:-1]
    if len(token)>=2 and token[0]=="'" and token[-1]=="'":
        return token[1:-1].replace("''","'")
    return token

def _yaml_split_flow(s):
    parts=[]; cur=[]; depth=0; in_s=in_d=False; esc=False
    for ch in s:
        if in_d:
            cur.append(ch)
            if esc: esc=False
            elif ch=='\\': esc=True
            elif ch=='"': in_d=False
            continue
        if in_s:
            cur.append(ch)
            if ch=="'": in_s=False
            continue
        if ch=='"': in_d=True; cur.append(ch)
        elif ch=="'": in_s=True; cur.append(ch)
        elif ch in '[{': depth+=1; cur.append(ch)
        elif ch in ']}': depth-=1; cur.append(ch)
        elif ch==',' and depth==0:
            parts.append("".join(cur).strip()); cur=[]
        else: cur.append(ch)
    if cur or s.strip()=="": parts.append("".join(cur).strip())
    return parts

def _yaml_parse_flow_or_scalar(text,line,col):
    text=text.strip(); col=col+(len(text)-len(text.lstrip())) if False else col
    if text.startswith("!"):
        # tagged node: !Tag rest
        m=re.match(r'!([A-Za-z0-9_\-]+)\s*(.*)$',text,re.S)
        if m:
            rest=m.group(2).strip()
            inner=_yaml_parse_flow_or_scalar(rest,line,col) if rest else YNode("scalar","",line,col)
            inner.tag=m.group(1)
            return inner
    if text.startswith("[") and text.rstrip().endswith("]"):
        inner=text.strip()[1:-1].strip()
        if inner=="": return YNode("list",[],line,col)
        return YNode("list",[_yaml_parse_flow_or_scalar(p,line,col) for p in _yaml_split_flow(inner)],line,col)
    if text.startswith("{") and text.rstrip().endswith("}"):
        inner=text.strip()[1:-1].strip(); pairs=[]
        if inner:
            for p in _yaml_split_flow(inner):
                if ":" in p:
                    k,v=p.split(":",1); pairs.append((_yaml_unquote(k.strip()),_yaml_parse_flow_or_scalar(v.strip(),line,col)))
                else:
                    pairs.append((_yaml_unquote(p),YNode("scalar","",line,col)))
        return YNode("map",pairs,line,col)
    return YNode("scalar",_yaml_unquote(text),line,col)

def parse_yaml_subset(text):
    # returns YNode; an empty/comments-only document has kind 'empty'
    raw_lines=text.splitlines()
    entries=[]  # (indent, content, lineno)
    for idx,raw in enumerate(raw_lines,1):
        if "\t" in raw[:len(raw)-len(raw.lstrip())]:
            raise YamlParseError("found character that cannot start any token, while scanning for the next token")
        stripped=_yaml_strip_comment(raw)
        if stripped.strip()=="" or stripped.strip() in ("---","..."):
            continue
        indent=len(stripped)-len(stripped.lstrip(' '))
        entries.append([indent,stripped.strip(),idx])
    if not entries:
        return YNode("empty",None,1,1)
    pos=[0]
    def parse_block(min_indent):
        if pos[0]>=len(entries): return YNode("scalar","",1,1)
        indent,content,lineno=entries[pos[0]]
        if indent<min_indent:
            return YNode("scalar","",lineno,1)
        # sequence?
        if content=="-" or content.startswith("- "):
            items=[]; start_line=lineno
            while pos[0]<len(entries):
                ind,cont,ln=entries[pos[0]]
                if ind!=indent or not (cont=="-" or cont.startswith("- ")): break
                rest=cont[1:].lstrip(); pos[0]+=1
                if rest=="":
                    # nested block must be deeper; if next is same/deeper treat
                    if pos[0]<len(entries) and entries[pos[0]][0]>indent:
                        items.append(parse_block(entries[pos[0]][0]))
                    else: items.append(YNode("scalar","",ln,ind+1))
                elif ':' in rest and not rest.startswith(('"',"'",'[','{')):
                    # inline mapping start within a list item: synthesise a temp entry
                    # Reinsert as an entry with indent+2 and parse a mapping block.
                    entries.insert(pos[0],[indent+2,rest,ln])
                    # adjust: parse mapping starting at inserted entry; it and following >indent entries
                    items.append(parse_block(indent+2))
                else:
                    items.append(_yaml_parse_flow_or_scalar(rest,ln,ind+3))
            return YNode("list",items,start_line,indent+1)
        # mapping? find a colon separating key (not in quotes/flow)
        def find_colon(s):
            in_s=in_d=False; depth=0
            for i,ch in enumerate(s):
                if in_d:
                    if ch=='"': in_d=False
                elif in_s:
                    if ch=="'": in_s=False
                else:
                    if ch=='"': in_d=True
                    elif ch=="'": in_s=True
                    elif ch in '[{': depth+=1
                    elif ch in ']}': depth-=1
                    elif ch==':' and depth==0 and (i+1==len(s) or s[i+1].isspace()):
                        return i
            return -1
        if find_colon(content)>=0:
            pairs=[]; start_line=lineno
            while pos[0]<len(entries):
                ind,cont,ln=entries[pos[0]]
                if ind!=indent: break
                ci=find_colon(cont)
                if ci<0: break
                key=_yaml_unquote(cont[:ci].strip())
                rest=cont[ci+1:].strip(); pos[0]+=1
                if rest=="":
                    if pos[0]<len(entries) and entries[pos[0]][0]>indent:
                        val=parse_block(entries[pos[0]][0])
                    else:
                        val=YNode("scalar","",ln,ind+ci+2)
                elif rest in ("|",">","|-",">-","|+",">+"):
                    # block scalar: collect following deeper-indented raw entries (approximation)
                    buf=[]
                    while pos[0]<len(entries) and entries[pos[0]][0]>indent:
                        buf.append(entries[pos[0]][1]); pos[0]+=1
                    textv=("\n" if rest.startswith("|") else " ").join(buf)
                    val=YNode("scalar",textv,ln,ind+ci+2)
                else:
                    val=_yaml_parse_flow_or_scalar(rest,ln,ind+ci+3)
                pairs.append((key,val))
            return YNode("map",pairs,start_line,indent+1)
        # scalar document / flow
        node=_yaml_parse_flow_or_scalar(content,lineno,indent+1); pos[0]+=1
        return node
    doc=parse_block(entries[0][0])
    return doc

def _yaml_scalar_text(node):
    if node.kind=="scalar": return node.value
    return None

def _yaml_is_null(node):
    if node.kind=="empty": return True
    if node.kind!="scalar": return False
    return node.value in ("","~","null","Null","NULL")

def _yaml_type_name(node):
    if node.kind=="list": return "sequence"
    if node.kind=="map": return "map"
    if node.kind=="empty": return "unit value"
    v=node.value
    if v in ("","~","null","Null","NULL"): return "unit value"
    if v in ("true","false","True","False","TRUE","FALSE"): return f"boolean `{v.lower()}`" if v.lower() in ("true","false") else f"boolean `{v}`"
    if re.fullmatch(r'[-+]?\d+',v): return f"integer `{v}`"
    if re.fullmatch(r'[-+]?(\d+\.\d*|\.\d+|\d+)([eE][-+]?\d+)?',v): return f"floating point `{v}`"
    return f'string "{v}"'

class Config:
    def __init__(self):
        self.default_editor=None
        self.exec_map=None  # dict[str,list[str]] or None
        self.ignore_case=False
        self.match_vim_exit_behavior=False
        # colors as ('ansi',code) / ('rgb',r,g,b)
        self.dir_fg=('ansi',14)
        self.file_fg=('ansi',15)
        self.symlink_fg=('ansi',11)
        self.dirty_fg=('ansi',1)

COLOR_VARIANTS=["Black","Red","Green","Yellow","Blue","Magenta","Cyan","White","LightBlack","LightRed","LightGreen","LightYellow","LightBlue","LightMagenta","LightCyan","LightWhite","Rgb","AnsiValue"]

def _parse_color_node(node,field_path):
    if node.tag=="AnsiValue":
        txt=_yaml_scalar_text(node)
        if txt is None or not re.fullmatch(r'\d+',txt or "") or int(txt)>255:
            raise ConfigError(f"{field_path}: invalid type: {_yaml_type_name(node)}, expected u8 at line {node.line} column {node.col}")
        return ('ansi',int(txt))
    if node.tag=="Rgb":
        if node.kind!="list" or len(node.value)!=3:
            raise ConfigError(f"{field_path}: invalid type: {_yaml_type_name(node)}, expected tuple variant Colorname::Rgb at line {node.line} column {node.col}")
        vals=[]
        for el in node.value:
            t=_yaml_scalar_text(el)
            if t is None or not re.fullmatch(r'\d+',t or "") or int(t)>255:
                raise ConfigError(f"{field_path}: invalid type: {_yaml_type_name(el)}, expected u8 at line {el.line} column {el.col}")
            vals.append(int(t))
        return ('rgb',vals[0],vals[1],vals[2])
    if node.tag:
        raise ConfigError(f"color: unknown variant `{node.tag}`, expected one of `"+"`, `".join(COLOR_VARIANTS)+f"` at line {node.line} column {node.col}")
    if node.kind!="scalar":
        raise ConfigError(f"{field_path}: invalid type: {_yaml_type_name(node)}, expected a YAML tag starting with '!' at line {node.line} column {node.col}")
    v=node.value
    if v in COLOR_VARIANTS[:16]:
        return ('ansi',COLOR_VARIANTS.index(v))
    if v=="Rgb":
        raise ConfigError(f"{field_path}: invalid type: unit variant, expected tuple variant at line {node.line} column {node.col}")
    if v=="AnsiValue":
        raise ConfigError(f"{field_path}: invalid type: unit variant, expected newtype variant at line {node.line} column {node.col}")
    raise ConfigError(f"{field_path}: unknown variant `{v}`, expected one of `"+"`, `".join(COLOR_VARIANTS)+f"` at line {node.line} column {node.col}")

class ConfigError(Exception):
    pass

def config_from_yaml(text):
    try:
        doc=parse_yaml_subset(text)
    except ConfigError:
        raise
    except Exception as e:
        raise ConfigError(str(e))
    cfg=Config()
    if doc.kind=="empty":
        return cfg
    if doc.kind!="map":
        raise ConfigError(f"invalid type: {_yaml_type_name(doc)}, expected struct Config")
    seen=set()
    for key,node in doc.value:
        if key in ("default","exec","color","ignore_case","match_vim_exit_behavior"):
            if key in seen:
                raise ConfigError(f"duplicate field `{key}`")
            seen.add(key)
        if key=="default":
            if _yaml_is_null(node): cfg.default_editor=None
            elif node.kind=="scalar": cfg.default_editor=node.value
            else: raise ConfigError(f"default: invalid type: {_yaml_type_name(node)}, expected a string at line {node.line} column {node.col}")
        elif key in ("ignore_case","match_vim_exit_behavior"):
            if _yaml_is_null(node):
                val=False
            elif node.kind=="scalar" and node.value.lower() in ("true","false") and node.value in ("true","false","True","False","TRUE","FALSE"):
                val=node.value.lower()=="true"
            else:
                raise ConfigError(f"{key}: invalid type: {_yaml_type_name(node)}, expected a boolean at line {node.line} column {node.col}")
            if key=="ignore_case": cfg.ignore_case=val
            else: cfg.match_vim_exit_behavior=val
        elif key=="exec":
            if _yaml_is_null(node): cfg.exec_map=None
            elif node.kind!="map":
                raise ConfigError(f"exec: invalid type: {_yaml_type_name(node)}, expected a map at line {node.line} column {node.col}")
            else:
                m={}
                for ck,cv in node.value:
                    if cv.kind=="list":
                        vals=[]
                        for el in cv.value:
                            if el.kind!="scalar":
                                raise ConfigError(f"exec: invalid type: {_yaml_type_name(el)}, expected a string at line {el.line} column {el.col}")
                            vals.append(el.value)
                        m[ck]=vals
                    elif cv.kind=="scalar":
                        # serde would reject a scalar where a Vec is expected
                        raise ConfigError(f"exec: invalid type: {_yaml_type_name(cv)}, expected a sequence at line {cv.line} column {cv.col}")
                    else:
                        raise ConfigError(f"exec: invalid type: {_yaml_type_name(cv)}, expected a sequence at line {cv.line} column {cv.col}")
                cfg.exec_map=m
        elif key=="color":
            if _yaml_is_null(node):
                pass
            elif node.kind!="map":
                raise ConfigError(f"color: invalid type: {_yaml_type_name(node)}, expected struct ConfigColor at line {node.line} column {node.col}")
            else:
                fields={}
                for ck,cv in node.value:
                    if ck in fields:
                        raise ConfigError(f"duplicate field `{ck}`")
                    fields[ck]=cv
                for req in ("dir_fg","file_fg","symlink_fg","dirty_fg"):
                    if req not in fields:
                        raise ConfigError(f"color: missing field `{req}` at line {node.line} column {node.col}")
                cfg.dir_fg=_parse_color_node(fields["dir_fg"],"color.dir_fg")
                cfg.file_fg=_parse_color_node(fields["file_fg"],"color.file_fg")
                cfg.symlink_fg=_parse_color_node(fields["symlink_fg"],"color.symlink_fg")
                cfg.dirty_fg=_parse_color_node(fields["dirty_fg"],"color.dirty_fg")
        else:
            continue
    return cfg

def fg_seq(color):
    if color is None: return "\x1b[39m"
    if color[0]=='ansi': return f"\x1b[38;5;{color[1]}m"
    return f"\x1b[38;2;{color[1]};{color[2]};{color[3]}m"

