                        raise ConfigError(f"exec: invalid type: {_yaml_type_name(cv)}, expected a sequence at line {cv.line} column {cv.col}")
                    else:
                        raise ConfigError(f"exec: invalid type: {_yaml_type_name(cv)}, expected a sequence at line {cv.line} column {cv.col}")
