            if len(b)==1: return None,0,True
            # CSI / SS3
            if b[1:2]==b'[':
                # find final byte 0x40-0x7e
                i=2
                while i<len(b) and not (0x40<=b[i]<=0x7e): i+=1
                if i>=len(b): return None,0,True
                seq=b[2:i]; final=chr(b[i]); consumed=i+1
                return self._csi(seq,final,b[1:2]),consumed,False
            if b[1:2]==b'O':
                if len(b)<3: return None,0,True
                final=chr(b[2])
                mp={'A':"up",'B':"down",'C':"right",'D':"left",'H':"home",'F':"end",'P':"f1",'Q':"f2",'R':"f3",'S':"f4"}
                return KeyEvent(mp.get(final,"unknown")),3,False
            # Alt + next key (byte or utf8 char)
            ev,consumed,need=self._parse_one(b[1:])
            if need: return None,0,True
            if ev is None: return None,1+consumed,False
            ev.mods|=ALT
            return ev,1+consumed,False
        if c==0x0d: return KeyEvent("enter"),1,False
        if c==0x0a: return KeyEvent("char","j",CTRL),1,False
        if c==0x09: return KeyEvent("tab"),1,False
        if c==0x7f: return KeyEvent("backspace"),1,False
        if c==0x08: return KeyEvent("char","h",CTRL),1,False
        if 1<=c<=26:
            return KeyEvent("char",chr(ord('a')+c-1),CTRL),1,False
        if c==0: return KeyEvent("char"," ",CTRL),1,False
        if 0x1c<=c<=0x1f:
            mp={0x1c:'\\',0x1d:']',0x1e:'^',0x1f:'_'}
            return KeyEvent("char",mp[c],CTRL),1,False
        # utf-8 char
        if c<0x80:
            ch=chr(c)
            mods=SHIFT if ch.isupper() else 0
            return KeyEvent("char",ch,mods),1,False
        # decode multibyte
        for ln in (2,3,4):
            if len(b)>=ln:
                try:
                    ch=b[:ln].decode("utf-8")
                    if len(ch)==1:
                        return KeyEvent("char",ch,SHIFT if ch.isupper() else 0),ln,False
                except Exception: pass
        if len(b)<4:
            # may be a split sequence; if first byte announces a longer seq wait
            need=2 if c>=0xc0 and c<0xe0 else 3 if c<0xf0 else 4
            if len(b)<need: return None,0,True
        return None,1,False
    def _csi(self,seq,final,kind=b'['):
        s=seq.decode("ascii","ignore")
        mods=0; nums=[]
        if s.startswith("<"): return KeyEvent("unknown")  # mouse
        parts=s.split(";") if s else []
        try: nums=[int(p) if p else 0 for p in parts]
        except Exception: nums=[]
        if len(nums)>=2 and nums[1]:
            m=nums[1]-1
            if m&1: mods|=SHIFT
            if m&2: mods|=ALT
            if m&4: mods|=CTRL
        if final=='Z': return KeyEvent("backtab",None,SHIFT)
        mp={'A':"up",'B':"down",'C':"right",'D':"left",'H':"home",'F':"end",'E':"unknown",'P':"f1",'Q':"f2",'R':"f3",'S':"f4"}
        if final in mp: return KeyEvent(mp[final],None,mods)
        if final=='~':
            n=nums[0] if nums else 0
            mp2={1:"home",2:"insert",3:"delete",4:"end",5:"pageup",6:"pagedown",7:"home",8:"end",11:"f1",12:"f2",13:"f3",14:"f4",15:"f5",17:"f6",18:"f7",19:"f8",20:"f9",21:"f10",23:"f11",24:"f12",200:"paste_start",201:"paste_end"}
            return KeyEvent(mp2.get(n,"unknown"),None,mods)
        if final=='u':
            # kitty keyboard protocol - not expected from tmux normally
            if nums:
                try: return KeyEvent("char",chr(nums[0]),mods)
                except Exception: pass
            return KeyEvent("unknown")
        return KeyEvent("unknown",None,mods)

# ---------------- screen buffer ----------------
class Cell:
    __slots__=("ch","fg","bg","bold","reverse","width")
    def __init__(self):
        self.ch=" "; self.fg=None; self.bg=None; self.bold=False; self.reverse=False; self.width=1

class Screen:
    def __init__(self,w,h):
        self.w=max(w,1); self.h=max(h,1)
        self.cells=[[Cell() for _ in range(self.w)] for _ in range(self.h)]
    def put_text(self,x,y,text,fg=None,bg=None,bold=False,reverse=False,max_x=None):
        if y<0 or y>=self.h: return x
        if max_x is None: max_x=self.w
        cx=x
        for ch in text:
            cw=char_width(ch)
            if cw==0:
                # attach zero-width chars to previous cell if possible
                if 0<=cx-1<self.w:
                    self.cells[y][cx-1].ch+=ch
                elif 0<=cx<self.w:
                    # store on current blank cell (e.g. BOM at start)
                    c=self.cells[y][cx]; c.ch=ch; c.fg=fg; c.bg=bg; c.bold=bold; c.reverse=reverse; c.width=1
                    cx+=1
                continue
            if cx+cw>max_x or cx>=self.w:
                break
            if cx<0:
                cx+=cw; continue
            c=self.cells[y][cx]
            c.ch=ch; c.fg=fg; c.bg=bg; c.bold=bold; c.reverse=reverse; c.width=cw
            if cw==2 and cx+1<self.w:
                c2=self.cells[y][cx+1]; c2.ch=""; c2.fg=fg; c2.bg=bg; c2.bold=bold; c2.reverse=reverse; c2.width=0
            cx+=cw
        return cx
    def fill(self,x,y,width,fg=None,bg=None,bold=False,reverse=False):
        if y<0 or y>=self.h: return
        for cx in range(max(x,0),min(x+width,self.w)):
            c=self.cells[y][cx]; c.ch=" "; c.fg=fg; c.bg=bg; c.bold=bold; c.reverse=reverse; c.width=1
    def render(self):
        out=[]
        out.append("\x1b[2J")
        for y,row in enumerate(self.cells):
            out.append(f"\x1b[{y+1};1H")
            cur=None
            x=0
            while x<self.w:
                c=row[x]
                if c.width==0:
                    x+=1; continue
                style=(c.fg,c.bg,c.bold,c.reverse)
                if style!=cur:
                    out.append("\x1b[0m")
                    if c.bold: out.append("\x1b[1m")
                    if c.reverse: out.append("\x1b[7m")
                    if c.fg is not None: out.append(fg_seq(c.fg))
                    if c.bg is not None:
                        bg=c.bg
                        if bg[0]=='ansi': out.append(f"\x1b[48;5;{bg[1]}m")
                        else: out.append(f"\x1b[48;2;{bg[1]};{bg[2]};{bg[3]}m")
                    cur=style
                out.append(c.ch if c.ch else " ")
                x+= max(c.width,1)
            # avoid wrapping on last column of last row? tmux handles pending wrap.
        out.append("\x1b[0m")
        return "".join(out)

