    # ---- movement ----
    def move_down(self,n=1):
        for _ in range(n):
            if not self.items: return
            if self.sel>=len(self.items)-1: return
            self.sel+=1
            lay=self.layout(); max_y=2+lay["capacity"]-1 if lay["capacity"]>0 else 2
            limit_y=self.term_h-5 if not (self.preview_on and self.split=="horizontal") else lay["list_h"]-5
            # observed cap: cursor stops 3 rows above the list bottom (i.e. at term_h-5
            # for a full-height list), then the window scrolls.
            if self.cursor_y<min(limit_y,max_y if max_y>2 else limit_y):
                self.cursor_y+=1
            else:
                # only scroll if the cursor is at/after the threshold
                if self.cursor_y>=limit_y:
                    self.skip+=1
                else:
                    self.cursor_y+=1
            self.preview_scroll=0

    def move_up(self,n=1):
        for _ in range(n):
            if not self.items: return
            if self.sel<=0: return
            self.sel-=1
            if self.cursor_y>5 or self.skip==0:
                if self.cursor_y>2: self.cursor_y-=1
                else:
                    if self.skip>0: self.skip-=1
            else:
                if self.skip>0: self.skip-=1
                elif self.cursor_y>2: self.cursor_y-=1
            self.preview_scroll=0

    def move_to_top(self):
        if not self.items:
            self.sel=0; self.skip=0; self.cursor_y=2; return
        self.sel=0; self.skip=0; self.cursor_y=2; self.preview_scroll=0

    def move_to_bottom(self):
        if not self.items: return
        lay=self.layout(); cap=lay["capacity"]; total=len(self.items)
        if cap>0 and total>cap:
            self.skip=total-cap
            self.cursor_y=2+cap-1
            self.sel=total-1
        else:
            if self.skip!=0:
                # observed quirk: first G with a scrolled (searched) small list
                # just resets the window to the top.
                self.skip=0; self.cursor_y=2; self.sel=0
            else:
                self.sel=total-1; self.cursor_y=2+total-1; self.skip=0
        self.preview_scroll=0

    def jump_to_index(self,idx):
        if not self.items: return
        idx=max(0,min(idx,len(self.items)-1))
        self.sel=idx; self.skip=idx; self.cursor_y=2; self.preview_scroll=0

    # ---- directory changes ----
    def _save_session(self):
        if 0<=self.session_ptr<len(self.sessions):
            s=self.sessions[self.session_ptr]
            s.path=self.cwd; s.sel=self.sel; s.skip=self.skip; s.y=self.cursor_y

    def _zoxide_add(self,path):
        if not self.has_zoxide: return
        try:
            subprocess.Popen(["zoxide","add",os.fsdecode(path)],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
        except Exception: pass

    def _record_jump(self,path):
        self.jumps.append(path); self.jump_ptr=len(self.jumps)-1

    def change_directory(self,target,kind="reset",record_jump=True,old_cwd=None):
        """target: bytes path (may be relative).  Returns True on success.
           kind: 'reset' fresh session, 'hl' session-stack navigation."""
        if old_cwd is None: old_cwd=self.cwd
        # resolve relative to current displayed directory
        if not os.path.isabs(target):
            target=os.path.join(self.cwd,target)
        try:
            canon=os.path.realpath(target)
            canon=os.fsencode(canon)
            # verify it is a directory by attempting to list it (like read_dir)
            with os.scandir(canon) as it:
                # force the open to happen; contents are re-read by load_items
                pass
        except OSError as e:
            self.set_warn(rust_io_error(e))
            self.show_marker=True
            return False
        prev_cwd=self.cwd
        # sessions
        restored=None
        if kind=="hl":
            self._save_session()
            # previous?
            if self.session_ptr>0 and self.sessions[self.session_ptr-1].path==canon:
                self.session_ptr-=1; restored=self.sessions[self.session_ptr]
            elif self.session_ptr+1<len(self.sessions) and self.sessions[self.session_ptr+1].path==canon:
                self.session_ptr+=1; restored=self.sessions[self.session_ptr]
            else:
                self.sessions=self.sessions[:self.session_ptr+1]
                self.sessions.append(SessionState(canon)); self.session_ptr=len(self.sessions)-1
        else:
            self.sessions=[SessionState(canon)]; self.session_ptr=0
        self.cwd=canon
        self.load_items()
        self.visual_anchor=None; self.preview_scroll=0; self.search_keyword=None
        self.clear_message(); self.pending=""; self.show_marker=True
        if restored is not None:
            if self.items:
                self.sel=min(restored.sel,len(self.items)-1); self.skip=restored.skip; self.cursor_y=restored.y
                self.apply_layout_change()
            else:
                self.sel=0; self.skip=0; self.cursor_y=2
        else:
            self.sel=0; self.skip=0; self.cursor_y=2
            if kind=="hl" and prev_cwd!=canon and os.path.dirname(prev_cwd)==canon:
                # going to a fresh parent: select the child we came from
                for i,it in enumerate(self.items):
                    if it.path==prev_cwd:
                        self.sel=i
                        if i>=3:
                            self.skip=i-3; self.cursor_y=5
                        else:
                            self.skip=0; self.cursor_y=2+i
                        break
        if record_jump:
            self._record_jump(canon)
        self._zoxide_add(canon)
        return True

    def go_parent(self):
        parent=os.path.dirname(self.cwd)
        if parent==self.cwd:
            return
        self.change_directory(parent,kind="hl")

    def open_item(self):
        item=self.current_item()
        if item is None: return
        if item.is_dir:
            self.change_directory(item.path,kind="hl")
        else:
            self.open_file(item,new_window=False)

    def jump_backward(self):
        if self.jump_ptr<=0: return
        self.jump_ptr-=1
        target=self.jumps[self.jump_ptr]
        # jumps load fresh and reset the session stack, without recording
        saved_ptr=self.jump_ptr; saved_jumps=list(self.jumps)
        ok=self.change_directory(target,kind="reset",record_jump=False)
        self.jumps=saved_jumps; self.jump_ptr=saved_ptr
        if not ok:
            # keep pointer where it moved (reference behaviour is obscure here)
            pass

    def jump_forward(self):
        if self.jump_ptr>=len(self.jumps)-1: return
        self.jump_ptr+=1
        target=self.jumps[self.jump_ptr]
        saved_ptr=self.jump_ptr; saved_jumps=list(self.jumps)
        self.change_directory(target,kind="reset",record_jump=False)
        self.jumps=saved_jumps; self.jump_ptr=saved_ptr

