    # ---- copy helpers ----
    def _copy_file(self,src,dst):
        # like Rust fs::copy: follows symlinks, copies permissions, not times
        shutil.copyfile(src,dst)
        try:
            st=os.stat(src); os.chmod(dst,stat.S_IMODE(st.st_mode))
        except OSError:
            pass

    def _copy_for_put(self,src,dst):
        # raises on error; mirrors observed put behaviour
        lst=os.lstat(src)
        if stat.S_ISLNK(lst.st_mode):
            if os.path.isdir(src):
                raise IsADirectoryError(21,os.strerror(21))
            self._copy_file(src,dst)  # raises for broken links
            return
        if stat.S_ISDIR(lst.st_mode):
            os.mkdir(dst)
            with os.scandir(src) as it: entries=list(it)
            for ent in entries:
                self._copy_for_put(os.path.join(src,os.fsencode(ent.name)),os.path.join(dst,os.fsencode(ent.name)))
            return
        self._copy_file(src,dst)

    def _copy_for_trash(self,src,dst):
        lst=os.lstat(src)
        if stat.S_ISLNK(lst.st_mode):
            if os.path.isdir(src):
                raise PanicError("") if False else _CannotCopy(src)
            if not os.path.exists(src):
                return  # broken link: skipped (no trash file), as observed
            self._copy_file(src,dst); return
        if stat.S_ISDIR(lst.st_mode):
            os.mkdir(dst)
            with os.scandir(src) as it: entries=list(it)
            for ent in entries:
                self._copy_for_trash(os.path.join(src,os.fsencode(ent.name)),os.path.join(dst,os.fsencode(ent.name)))
            return
        if stat.S_ISREG(lst.st_mode):
            self._copy_file(src,dst); return
        # other special files are skipped rather than blocking on them
        return

    def _remove_path(self,path):
        st=os.lstat(path)
        if stat.S_ISDIR(st.st_mode) and not stat.S_ISLNK(st.st_mode):
            shutil.rmtree(path)
        else:
            os.remove(path)

    def _new_dest_path(self,src,dest_dir):
        name_b=os.path.basename(src.rstrip(b"/")) if isinstance(src,bytes) else os.path.basename(src)
        # strip the trash timestamp prefix when putting from the trash dir
        td=trash_dir_bytes()
        if td and os.path.dirname(src)==td:
            m=re.match(br'^\d+_(.*)$',name_b,re.S)
            if m: name_b=m.group(1)
        cand=os.path.join(dest_dir,name_b)
        if not os.path.lexists(cand):
            return cand
        is_dir=False
        try: is_dir=os.path.isdir(src)
        except Exception: pass
        name=display_name_of_bytes(name_b) if False else name_b.decode("utf-8","surrogateescape")
        n=1
        while True:
            if is_dir:
                new_name=f"{name}_{n}"
            else:
                stem,ext=split_stem_ext(name)
                if ext is None: new_name=f"{stem}_{n}"
                else: new_name=f"{stem}_{n}.{ext}"
            cand=os.path.join(dest_dir,os.fsencode(new_name))
            if not os.path.lexists(cand): return cand
            n+=1

    # ---- registers ----
    def _shift_numbered(self):
        # 8->9, 7->8, ... 1->2 (old 9 dropped)
        for i in range(8,0,-1):
            k=str(i)
            if k in self.registers:
                self.registers[str(i+1)]=self.registers[k]
            elif str(i+1) in self.registers:
                del self.registers[str(i+1)]

    def _set_yank_registers(self,paths,target,is_delete):
        # target: None, or a single character as typed (alpha)
        if target is None:
            self.registers['"']=list(paths)
            if is_delete:
                self._shift_numbered(); self.registers['1']=list(paths)
            else:
                self.registers['0']=list(paths)
            return
        is_append=target.isupper()
        key=target.lower()
        if is_append and key in self.registers:
            self.registers[key]=list(self.registers[key])+list(paths)
        else:
            self.registers[key]=list(paths)
        self.registers['"']=list(paths)
        if is_delete:
            self._shift_numbered(); self.registers['1']=list(paths)

    def do_yank(self,paths,target=None,visual=False):
        if not paths: return
        self._set_yank_registers(paths,target,is_delete=False)
        if visual:
            msg=f"{len(paths)} items yanked"
        else:
            msg="1 item yanked." if len(paths)==1 else f"{len(paths)} items yanked."
        self.set_info(msg)

    # ---- put ----
    def do_put(self,register=None):
        # register: None -> unnamed; else single character
        if register is None:
            paths=self.registers.get('"')
            if not paths: return
        else:
            key=register.lower() if register.isalpha() else register
            paths=self.registers.get(key)
            if paths is None:
                self.set_warn("Register not found."); return
            if not paths: return
        if self.is_readonly:
            self.set_warn("Cannot put into this directory."); return
        start=time.monotonic()
        self.logger.info("PUT: Processing...")
        made=[]  # (src,dst)
        count=0
        for src in list(paths):
            dst=self._new_dest_path(src,self.cwd)
            try:
                self._copy_for_put(src,dst)
                made.append((src,dst)); count+=1
            except Exception:
                continue
        elapsed=time.monotonic()-start
        # record the operation even if nothing could be copied (observed)
        self._push_op(Operation("PUT",{"pairs":made}))
        dests=[d for _,d in made]
        self.logger.info(f"PUT: {rust_debug_list(dests)}")
        if count==1: msg=f"1 item inserted. [{elapsed:.2f}s]"
        else: msg=f"{count} items inserted. [{elapsed:.2f}s]"
        self.reload_preserve()
        self._finish_op_message(msg)

    def _finish_op_message(self,msg,warn=False):
        # The reference appears not to show these messages when the list is empty.
        if not self.items:
            if warn: self.logger.warn(msg)
            else: self.logger.info(msg)
            self.clear_message(); return
        if warn: self.set_warn(msg,log=False); self.logger.warn(msg)
        else: self.set_info(msg,log=False); self.logger.info(msg)

    def _push_op(self,op):
        self.ops=self.ops[:self.op_ptr]
        self.ops.append(op); self.op_ptr=len(self.ops)

    # ---- delete ----
    def do_delete(self,paths,target=None,visual=False):
        if not paths: return
        if self.is_readonly:
            self.set_warn("Cannot delete item in this directory."); return
        start=time.monotonic()
        self.logger.info("DELETE: Processing...")
        td=trash_dir_bytes()
        pairs=[]  # (original, trash_dest)
        try:
            for src in list(paths):
                if td:
                    try: os.makedirs(td,exist_ok=True)
                    except Exception: pass
                    ts=int(time.time())
                    base=os.path.basename(src.rstrip(b"/"))
                    dest=os.path.join(td,os.fsencode(f"{ts}_")+base)
                else:
                    dest=b""
                if td:
                    self._copy_for_trash(src,dest)
                pairs.append((src,dest))
        except _CannotCopy as e:
            self.reload_preserve()
            self.set_warn(f'Error: Cannot copy -> {rust_path_debug(e.path)}')
            return
        except OSError as e:
            self.reload_preserve()
            self.set_warn(rust_io_error(e)); return
        # remove originals
        for src,_ in pairs:
            try: self._remove_path(src)
            except OSError as e:
                self.reload_preserve(); self.set_warn(rust_io_error(e)); return
        elapsed=time.monotonic()-start
        trash_paths=[d for _,d in pairs]
        self._set_yank_registers(trash_paths,target,is_delete=True)
        self._push_op(Operation("DELETE",{"pairs":pairs}))
        self.logger.info(f"DELETE: {rust_debug_list(paths)}")
        if len(paths)==1: msg=f"1 item deleted. [{elapsed:.2f}s]"
        else: msg=f"{len(paths)} items deleted [{elapsed:.2f}s]"
        self.reload_preserve()
        self._finish_op_message(msg)

    # ---- undo / redo ----
    def do_undo(self):
        if self.op_ptr<=0:
            self.set_info("No operations left."); return
        op=self.ops[self.op_ptr-1]
        try:
            if op.kind=="PUT":
                for _,dst in op.data["pairs"]:
                    if os.path.lexists(dst): self._remove_path(dst)
                msg="UNDONE: PUT"; self.set_info(msg,log=False)
                self.logger.info(msg); self.logger.info(f"UNDO: PUT {rust_debug_list([d for _,d in op.data['pairs']])}")
            elif op.kind=="DELETE":
                for orig,trash in op.data["pairs"]:
                    if trash and os.path.lexists(trash):
                        if os.path.lexists(orig):
                            # restoring onto an existing path: remove files, overwrite dirs by copy
                            try: self._remove_path(orig)
                            except OSError: pass
                        self._copy_for_put(trash,orig)
                msg="UNDONE: DELETE"; self.set_info(msg,log=False)
                self.logger.info(msg); self.logger.info(f"UNDO: DELETE {rust_debug_list([o for o,_ in op.data['pairs']])}")
            elif op.kind=="RENAME":
                for old,new in op.data["pairs"]:
                    os.rename(new,old)
                msg="UNDONE: RENAME"; self.set_info(msg,log=False)
                self.logger.info(msg); self.logger.info(f"UNDO: RENAME {rust_debug_list([o for o,_ in op.data['pairs']])}")
            else:
                return
        except OSError as e:
            self.reload_preserve(); self.set_warn(rust_io_error(e)); return
        self.op_ptr-=1
        self.reload_preserve()
        if not self.items:
            self.clear_message()

    def do_redo(self):
        if self.op_ptr>=len(self.ops):
            self.set_info("No operations left."); return
        op=self.ops[self.op_ptr]
        try:
            if op.kind=="PUT":
                for src,dst in op.data["pairs"]:
                    if not os.path.lexists(dst):
                        self._copy_for_put(src,dst)
                msg="REDONE: PUT"; self.set_info(msg,log=False)
