    # ---- line input ----
    def start_line_input(self,kind,item=None):
        labels={"colon":":","search":"/","new_file":"New file: ","new_dir":"New directory: ","rename":"New name: ","zoxide":"z"}
        text=item.name if kind=="rename" and item else ""
        self.line_input={"kind":kind,"label":labels[kind],"text":text,"cursor":len(text),"item":item,"ctrl_r":False}
        self.pending=""
        self.show_marker=(kind=="rename")
        if kind!="rename":
            self.visual_anchor=None

    def cancel_line_input(self):
        self.line_input=None; self.show_marker=True; self.clear_message()

    def _search_incremental(self):
        self.show_marker=True
        if not self.line_input: return
        kw=self.line_input["text"]
        for i,it in enumerate(self.items):
            if self._matches(it,kw):
                self.jump_to_index(i); return

    def handle_line_input(self,ev):
        li=self.line_input; kind=li["kind"]
        if li.get("ctrl_r"):
            li["ctrl_r"]=False
            if ev.code=="char" and ev.ch:
                key=ev.ch.lower() if ev.ch.isalpha() else ev.ch
                vals=self.registers.get(key)
                if vals:
                    ins=" ".join(self._register_display_name(p) for p in vals)
                    li["text"]=li["text"][:li["cursor"]]+ins+li["text"][li["cursor"]:]
                    li["cursor"]+=len(ins)
                    if kind=="search": self._search_incremental()
            return
        if ev.code=="esc":
            self.cancel_line_input(); return
        if ev.code=="enter":
            text=li["text"]; item=li["item"]
            self.line_input=None; self.show_marker=True
            if kind=="new_file": self.do_create_file(text)
            elif kind=="new_dir": self.do_create_dir(text)
            elif kind=="rename": self.do_rename(item,text)
            elif kind=="colon": self.execute_command(text)
