    # ---- key handling ----
    def _selected_paths(self):
        if not self.items: return []
        if self.visual_anchor is not None:
            a=min(self.visual_anchor,self.sel); b=max(self.visual_anchor,self.sel)
            return [it.path for it in self.items[a:b+1]]
        it=self.current_item(); return [it.path] if it else []

    def _exit_keys(self,second):
        # second is 'Z' or 'Q' completing ZZ/ZQ
        vim=self.config.match_vim_exit_behavior
        if second=="Z":
            return self.request_exit(write_lwd=vim)
        else:
            return self.request_exit(write_lwd=not vim)

    def handle_pending(self,ev):
        buf=self.pending
        if ev.code!="char" or not ev.ch:
            self.pending=""; self.clear_message(); self.show_marker=True; return
        ch=ev.ch
        newbuf=buf+ch
        # quote-register sequences
        if buf.startswith('"'):
            if self.visual_anchor is not None:
                if len(newbuf)==2:
                    self.pending=newbuf; return
                if len(newbuf)==3:
                    self.pending=""
                    reg=newbuf[1]; op=newbuf[2]
                    if op in ("y","d") and reg.isalpha():
                        paths=self._selected_paths(); was_visual=True
                        self.visual_anchor=None
                        if op=="y": self.do_yank(paths,target=reg,visual=True)
                        else: self.do_delete(paths,target=reg,visual=True)
                    elif op in ("y","d") and reg.isdigit():
                        self.visual_anchor=None; self.clear_message()
                    elif op in ("y","d"):
                        self.visual_anchor=None; self.set_warn("Input not supported.")
                    else:
                        # like "aP in visual: no support message observed for normal; just clear
                        self.clear_message()
                    self.show_marker=True; return
                self.pending=newbuf; return
            # normal mode register sequences
            if len(newbuf)==2:
                self.pending=newbuf; return
            if len(newbuf)==3:
                reg=newbuf[1]; op=newbuf[2]
                if op=="p":
                    self.pending=""
                    if reg.isalnum(): self.do_put(register=reg)
                    else: self.set_warn("Input not supported.")
                    self.show_marker=True; return
                self.pending=newbuf; return
            if len(newbuf)>=4:
                self.pending=""
                reg=newbuf[1]; op=newbuf[2]; op2=newbuf[3]
                if op in ("y","d") and op2==op:
                    if reg.isalpha():
                        item=self.current_item(); paths=[item.path] if item else []
                        if op=="y": self.do_yank(paths,target=reg)
                        else: self.do_delete(paths,target=reg)
                    elif reg.isdigit():
                        self.clear_message()  # observed no-op (stale display ignored)
                    else:
                        self.set_warn("Input not supported.")
                else:
                    self.clear_message()
                self.show_marker=True; return
            self.pending=newbuf; return
        # two-key sequences gg/dd/yy/ZZ/ZQ
        self.pending=""
        if newbuf=="gg":
            self.move_to_top(); self.clear_message()
        elif newbuf=="dd":
            item=self.current_item(); self.do_delete([item.path] if item else [])
        elif newbuf=="yy":
            item=self.current_item(); self.do_yank([item.path] if item else [])
        elif newbuf in ("ZZ","ZQ"):
            self.show_marker=True
            self._exit_keys(newbuf[1])
            return
        else:
            self.clear_message()
        self.show_marker=True

    def handle_help(self,ev):
        if ev.code=="char" and ev.ch=="j" and not (ev.mods&CTRL) and not (ev.mods&ALT):
            self.help_scroll+=1; return
        if ev.code=="char" and ev.ch=="k" and not (ev.mods&CTRL) and not (ev.mods&ALT):
            self.help_scroll=max(0,self.help_scroll-1); return
        if ev.code=="down":
            self.help_scroll+=1; return
        if ev.code=="up":
            self.help_scroll=max(0,self.help_scroll-1); return
        self.mode="normal"

    def handle_confirm_empty(self,ev):
        self.mode="normal"
        if ev.code=="char" and ev.ch in ("y","Y"):
            self.do_empty_trash()
        else:
            self.clear_message()

    def handle_event(self,ev):
        if self.mode=="help":
            self.handle_help(ev); return
        if self.mode=="confirm_empty":
            self.handle_confirm_empty(ev); return
        if self.line_input is not None:
            self.handle_line_input(ev); return
        # Alt preview scrolling (only when no pending sequence)
        is_alt_down=(ev.mods&ALT) and ((ev.code=="char" and ev.ch=="j") or ev.code=="down")
        is_alt_up=(ev.mods&ALT) and ((ev.code=="char" and ev.ch=="k") or ev.code=="up")
        if (is_alt_down or is_alt_up) and not self.pending:
            if self.preview_on:
                if is_alt_down: self.preview_scroll+=1
                else: self.preview_scroll=max(0,self.preview_scroll-1)
            return
        if self.pending:
            self.handle_pending(ev); return
        self.handle_normal(ev)

    def handle_normal(self,ev):
        # non-character keys first
        if ev.code in ("down","up","left","right","enter","backspace","esc","tab"):
            if ev.mods&CTRL:
                return
            if ev.code=="down": self.move_down()
            elif ev.code=="up": self.move_up()
            elif ev.code=="left": self.go_parent()
            elif ev.code=="right": self.open_item()
            elif ev.code=="enter": self.open_item()
            elif ev.code=="backspace": self.toggle_hidden()
            elif ev.code=="tab": self.jump_forward()
            elif ev.code=="esc":
                self.visual_anchor=None; self.clear_message(); self.show_marker=True
            return
        if ev.code!="char" or not ev.ch:
            return
        ch=ev.ch
        if ev.mods&CTRL:
            lay=self.layout()
            if ch=="d": self.move_down(max(lay["list_h"]//2,1))
            elif ch=="u": self.move_up(max(lay["list_h"]//2,1))
            elif ch=="o": self.jump_backward()
            elif ch=="i": self.jump_forward()
            elif ch=="r": self.do_redo()
            return
        if ev.mods&ALT:
            return
        visual=self.visual_anchor is not None
        # keys that start pending sequences
        if ch=='"':
            self.pending='"'; return
        if ch=="g":
            self.pending="g"; return
        if ch=="Z":
            self.pending="Z"; self.show_marker=False; return
        if not visual and ch=="d":
